import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        q = int(next(iterator))
    except StopIteration:
        return

    cost = {}

    for _ in range(q):
        t = int(next(iterator))
        v = int(next(iterator))
        u = int(next(iterator))

        if t == 1:
            w = int(next(iterator))

            while v != u:
                if v > u:
                    parent = v // 2
                    key = (parent, v) if parent < v else (v, parent)
                    cost[key] = cost.get(key, 0) + w
                    v = parent
                else:
                    parent = u // 2
                    key = (parent, u) if parent < u else (u, parent)
                    cost[key] = cost.get(key, 0.0) + w if isinstance(w, float) else cost.get(key, 0) + w
                    u = parent
        else:
            total_fee = 0
            curr_v, curr_u = v, u

            while curr_v != curr_u:
                if curr_v > curr_u:
                    parent = curr_v // 2
                    key = (parent, curr_v) if parent < curr_v else (curr_v, parent)
                    total_fee += cost.get(key, 0)
                    curr_v = parent
                else:
                    parent = curr_u // 2
                    key = (parent, curr_u) if parent < curr_u else (curr_u, parent)
                    total_fee += cost.get(key, 0) if isinstance(cost.get(key, 0), int) else cost.get(key, 0)
                    curr_u = parent

            print(total_fee)

if __name__ == "__main__":
    solve()
